<?php require_once __DIR__ . '/../includes/auth.php'; require_login(); require_once __DIR__ . '/../config/database.php'; require_once __DIR__ . '/../includes/functions.php'; $employee_id=(int)$_POST['employee_id']; $date=$_POST['work_date']; $status=$_POST['status']; $notes=trim($_POST['notes']??''); if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){set_flash('danger','Invalid date.'); redirect('create.php');} $stmt=$conn->prepare('INSERT INTO work_records(employee_id,work_date,status,notes) VALUES(?,?,?,?)'); $stmt->bind_param('isss',$employee_id,$date,$status,$notes); $stmt->execute(); set_flash('success','Work record added.'); redirect('index.php'); ?>
